async def save_progress_before_reload():
    return False

async def activate_update():
    return "activated"

async def apply_update(has_unsaved_progress):
    if has_unsaved_progress:
        saved = await save_progress_before_reload()
        if not saved:
            return "blocked"
    return await activate_update()
